import json,urllib.request
def call(name,args):
    r=urllib.request.Request("http://127.0.0.1:8000/inventory/mcp",json.dumps({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":name,"arguments":args}}).encode(),{"Content-Type":"application/json","Accept":"application/json,text/event-stream"})
    d=json.load(urllib.request.urlopen(r))
    return json.loads(d["result"]["content"][0]["text"])
def adjs(ref):
    out=[];p=1
    while p:
        d=call("list_adjustments",{"reference":ref,"page":p});out+=d["results"];p=d["next_page"]
    return out
