from mcp import *
import csv,sys
from collections import defaultdict
from fractions import Fraction
bom=defaultdict(lambda: defaultdict(list))
for r in csv.DictReader(open('/app/kits/kit-bom.csv')):
    bom[r['kit']][r['effective_from']].append((r['component'],int(r['qty'])))
subs={('KT-10','CP-202'):('CP-213',1),('KT-10','CP-203'):('CP-214',2),('KT-20','CP-204'):('CP-218',1)}
def explode(sku,q,date,req,kits):
    if sku not in bom: req[sku]+=q;return
    d=max(x for x in bom[sku] if x<=date)
    kits.add((sku,d))
    for c,n in bom[sku][d]: explode(c,q*n,date,req,kits)
lines={}
orders={}
for r in csv.DictReader(open('/app/kits/open-orders.csv')):
    k=(r['order'],r['line']);orders[r['order']]=r['created']
    if k not in lines or int(r['amendment'])>lines[k][0]: lines[k]=(int(r['amendment']),r)
rows=[];actions=[]
for o,date in sorted(orders.items()):
    req=defaultdict(int);kits=set()
    for (oo,l),(a,r) in lines.items():
        if oo==o and r['status']!='cancelled': explode(r['sku'],int(r['qty']),date,req,kits)
    A=adjs(o)
    res=defaultdict(int);pick=defaultdict(Fraction)
    for a in A:
        if a['warehouse']=='reserved': res[a['sku']]+=a['delta']
        if a['reason']=='shipment':
            s=a['sku'];n=-a['delta'];done=False
            if s in req: pick[s]+=n;continue
            for (k,d) in kits:
                for c,_ in bom[k][d]:
                    if subs.get((k,c),(None,))[0]==s and not done:
                        pick[c]+=Fraction(n,subs[(k,c)][1]);done=True
    for s in sorted(set(req)|set(res)):
        want=max(0,req[s]-pick[s]);assert want.denominator==1 if isinstance(want,Fraction) else 1
        want=int(want);d=want-res[s]
        rows.append((o,s,req[s],int(pick[s]) if pick[s].denominator==1 else float(pick[s]),want))
        if d: actions.append((o,s,d))
    print(o,sorted(kits),file=sys.stderr)
for a in actions: print(a)
csv_=open('/app/kit-reservations.csv','w');csv_.write('order,sku,required,picked,reserved\n')
for r in rows: csv_.write(','.join(map(str,r))+'\n')
import json;json.dump(actions,open('/tmp/actions.json','w'))
E
